  1→import {
  2→  Controller,
  3→  Post,
  4→  Get,
  5→  Param,
  6→  Body,
  7→  UseGuards,
  8→  UseInterceptors,
  9→  UploadedFile,
 10→  ParseFilePipe,
 11→  MaxFileSizeValidator,
 12→  Inject,
 13→  Res,
 14→  StreamableFile,
 15→  Request,
 16→  PayloadTooLargeException,
 17→} from '@nestjs/common';
 18→import { Response } from 'express';
 19→import { FileInterceptor } from '@nestjs/platform-express';
 20→import {
 21→  ApiTags,
 22→  ApiOperation,
 23→  ApiConsumes,
 24→  ApiBody,
 25→  ApiResponse,
 26→  ApiBearerAuth,
 27→} from '@nestjs/swagger';
 28→import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
 29→import { IPFS_PROVIDER, IpfsProvider } from './providers';
 30→import { UploadResponseDto, UnpinDto, UnpinResponseDto } from './dto';
 31→import { VaultService } from '../vault/vault.service';
 32→import { MetricsService } from '../metrics/metrics.service';
 33→import { RequestWithUser } from '../common/types';
 34→
 35→const MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB
 36→
 37→@ApiTags('IPFS')
 38→@ApiBearerAuth()
 39→@UseGuards(JwtAuthGuard)
 40→@Controller('ipfs')
 41→export class IpfsController {
 42→  constructor(
 43→    @Inject(IPFS_PROVIDER) private readonly ipfsProvider: IpfsProvider,
 44→    private readonly vaultService: VaultService,
 45→    private readonly metricsService: MetricsService
 46→  ) {}
 47→
 48→  @Post('upload')
 49→  @ApiOperation({
 50→    summary: 'Upload encrypted file to IPFS with quota tracking',
 51→    description:
 52→      'Pins encrypted file to IPFS, checks storage quota, and records the pin for quota tracking. All in one atomic request.',
 53→  })
 54→  @ApiConsumes('multipart/form-data')
 55→  @ApiBody({
 56→    schema: {
 57→      type: 'object',
 58→      properties: {
 59→        file: {
 60→          type: 'string',
 61→          format: 'binary',
 62→          description: 'Encrypted file blob (max 100MB)',
 63→        },
 64→      },
 65→      required: ['file'],
 66→    },
 67→  })
 68→  @ApiResponse({
 69→    status: 201,
 70→    description: 'File uploaded, pinned, and recorded successfully',
 71→    type: UploadResponseDto,
 72→  })
 73→  @ApiResponse({
 74→    status: 401,
 75→    description: 'Unauthorized - JWT token required',
 76→  })
 77→  @ApiResponse({
 78→    status: 413,
 79→    description: 'Storage quota exceeded',
 80→  })
 81→  @UseInterceptors(
 82→    FileInterceptor('file', {
 83→      limits: { fileSize: MAX_FILE_SIZE },
 84→    })
 85→  )
 86→  async upload(
 87→    @Request() req: RequestWithUser,
 88→    @UploadedFile(
 89→      new ParseFilePipe({
 90→        validators: [new MaxFileSizeValidator({ maxSize: MAX_FILE_SIZE })],
 91→      })
 92→    )
 93→    file: Express.Multer.File
 94→  ): Promise<UploadResponseDto> {
 95→    const hasQuota = await this.vaultService.checkQuota(req.user.id, file.size);
 96→    if (!hasQuota) throw new PayloadTooLargeException('Storage quota exceeded');
 97→    const result = await this.ipfsProvider.pinFile(file.buffer);
 98→    try {
 99→      await this.vaultService.recordPin(req.user.id, result.cid, result.size);
100→    } catch (err) {
101→      await this.ipfsProvider.unpinFile(result.cid).catch(() => undefined);
102→      throw err;
103→    }
104→    this.metricsService.fileUploads.inc();
105→    this.metricsService.fileUploadBytes.inc(result.size);
106→    return { cid: result.cid, size: result.size, recorded: true };
107→  }
108→
109→  @Post('unpin')
110→  @ApiOperation({
111→    summary: 'Unpin file from IPFS',
112→    description: 'Remove a pinned file from IPFS using its CID.',
113→  })
114→  @ApiResponse({
115→    status: 201,
116→    description: 'File unpinned successfully',
117→    type: UnpinResponseDto,
118→  })
119→  @ApiResponse({
120→    status: 401,
121→    description: 'Unauthorized - JWT token required',
122→  })
123→  async unpin(@Body() dto: UnpinDto): Promise<UnpinResponseDto> {
124→    await this.ipfsProvider.unpinFile(dto.cid);
125→    this.metricsService.fileUnpins.inc();
126→    return { success: true };
127→  }
128→
129→  @Get(':cid')
130→  @ApiOperation({
131→    summary: 'Get file from IPFS',
132→    description: 'Download an encrypted file from IPFS via the configured gateway.',
133→  })
134→  @ApiResponse({
135→    status: 200,
136→    description: 'File retrieved successfully',
137→    content: {
138→      'application/octet-stream': {
139→        schema: {
140→          type: 'string',
141→          format: 'binary',
142→        },
143→      },
144→    },
145→  })
146→  @ApiResponse({
147→    status: 401,
148→    description: 'Unauthorized - JWT token required',
149→  })
150→  @ApiResponse({
151→    status: 404,
152→    description: 'File not found',
153→  })
154→  async get(
155→    @Param('cid') cid: string,
156→    @Res({ passthrough: true }) res: Response
157→  ): Promise<StreamableFile> {
158→    const buffer = await this.ipfsProvider.getFile(cid);
159→    this.metricsService.fileDownloads.inc();
160→    res.set({
161→      'Content-Type': 'application/octet-stream',
162→      'Content-Length': buffer.length.toString(),
163→    });
164→    return new StreamableFile(buffer);
165→  }
166→}
