 1→import { Processor, WorkerHost } from '@nestjs/bullmq';
 2→import { Logger } from '@nestjs/common';
 3→import { Job } from 'bullmq';
 4→import { RepublishService } from './republish.service';
 5→import { MetricsService } from '../metrics/metrics.service';
 6→
 7→@Processor('republish')
 8→export class RepublishProcessor extends WorkerHost {
 9→  private readonly logger = new Logger(RepublishProcessor.name);
10→
11→  constructor(
12→    private readonly republishService: RepublishService,
13→    private readonly metricsService: MetricsService
14→  ) {
15→    super();
16→  }
17→
18→  async process(job: Job): Promise<void> {
19→    this.logger.log(`Republish job started: ${job.name} (id: ${job.id})`);
20→    this.metricsService.republishRuns.inc();
21→
22→    try {
23→      const result = await this.republishService.processRepublishBatch();
24→
25→      this.metricsService.republishEntriesProcessed.inc({ result: 'succeeded' }, result.succeeded);
26→      this.metricsService.republishEntriesProcessed.inc({ result: 'failed' }, result.failed);
27→
28→      this.logger.log(
29→        `Republish job complete: processed=${result.processed}, succeeded=${result.succeeded}, failed=${result.failed}`
30→      );
31→
32→      // If all entries failed and none succeeded, TEE might be down.
33→      // When TEE recovers, reactivate stale entries.
34→      if (result.processed > 0 && result.succeeded === 0 && result.failed === result.processed) {
35→        this.logger.warn('All republish entries failed. TEE worker may be unreachable.');
36→      }
37→    } catch (error) {
38→      const message = error instanceof Error ? error.message : String(error);
39→      this.logger.error(`Republish job failed: ${message}`);
40→      throw error; // Let BullMQ handle retry
41→    }
42→  }
43→}
